// Tipe Data untuk Dashboard (Dibuat otomatis oleh parse-excel.js)

export interface KabKota {
  no: number;
  regional: string;
  provinsiName: string;
  name: string;
  ipm: number;
  ikf: number;
  tik: number;
  idi: number;
  skorIpm: number;
  skorIkf: number;
  skorTik: number;
  skorIdi: number;
  avgSkor: number;
  rankNasional: number;
  rankRegional: number;
}

export interface Province {
  no: number;
  regional: string;
  name: string;
  ipm: number;
  ikf: number;
  tik: number;
  idi: number;
  skorIpm: number;
  skorIkf: number;
  skorTik: number;
  skorIdi: number;
  avgSkor: number;
  rankNasional: number;
  rankRegional: number;
  kabKotas: KabKota[];
}

export interface Regional {
  name: string;
  provinces: Province[];
}

export interface NationalAverages {
  ipm: number;
  ikf: number;
  tik: number;
  idi: number;
  avgSkor: number;
  totalProvinces: number;
  totalKabKota: number;
}

